//! @file
//! @brief Carbonite low-level scalar hashing utilities.
#pragma once

// This is a separate file to avoid always including the expensive <type_traits>
#include "Hash.h"

#include <memory>
#include <type_traits>

namespace carb
{
//! Runtime FNV-1a 64-bit hash of a scalar type.
//! @param type An scalar to hash.
//! @param hash The previous hash value or starting hash basis.
//! @returns A hash computed from the given parameters.
template <class T>
inline uint64_t hashScalar(const T& type, uint64_t hash = kFnvBasis)
{
    static_assert(std::is_scalar<T>::value, "Unsupported type for hashing");
    return hashBuffer(std::addressof(type), sizeof(type), hash);
}
} // namespace carb
